INSERT INTO products VALUES ('ADAP005','{"sku": "ADAP005", "nombre": "Adaptador de enchufe Europa a Latino negro", "modelo": null, "marca": null, "categoria": "Adaptadores", "descripcion": "Dale a tu enchufe europeo una conexión de dos clavijas planas. Este adaptador negro es una solución sencilla y compacta para conectar equipos con la forma de enchufe compatible. Su cuerpo con relieves facilita sujetarlo al colocarlo o retirarlo. Comprueba el ajuste y la tensión admitida por tu equipo antes de usarlo.", "caracteristicas": {"Color": "Negro", "Conector de salida visible": "Dos clavijas planas", "Clasificación": "Producto original", "Formato": "Europa a Latino", "Diseño": "Cuerpo compacto con relieves de agarre"}, "beneficios": [{"valor": "Europa → Latino", "titulo": "Adapta tu enchufe", "descripcion": "Para conectar la forma de enchufe compatible."}, {"valor": "2 clavijas planas", "titulo": "Conexión práctica", "descripcion": "Se conecta a tomas compatibles de dos ranuras planas."}, {"valor": "Cuerpo compacto", "titulo": "Llévalo contigo", "descripcion": "Pequeño y fácil de guardar entre tus accesorios."}], "imagen": "https://conectatech-ec.github.io/imagenes/adap005/ADAP005-01.webp", "banner": null, "url": "https://conectatech-ec.github.io/productos/adap005-adaptador-europa-latino-color-negro/", "entrega": "Quito: consulta retiro y opciones de entrega vigentes.", "garantia": null}',2.5,2.87,1,1792373091,'e9b6e4b70466952f1497e0c69d6ed45dae09ef50c73bfd7e9eec91ffe7830692') ON CONFLICT(sku) DO UPDATE SET data=excluded.data,promo=excluded.promo,pvp=excluded.pvp,available=excluded.available,verified_until=excluded.verified_until,inventory_digest=excluded.inventory_digest;
INSERT INTO products VALUES ('HUB001','{"sku": "HUB001", "nombre": "Hub USB 3.0 de 4 puertos USB-A", "modelo": "Hub USB 3.0", "marca": null, "categoria": "Hub", "descripcion": "Amplía un puerto USB-A en cuatro conexiones USB 3.0 dentro de un formato compacto. Su cable integrado de 30 cm permite organizar periféricos y memorias con acceso directo.", "caracteristicas": {"Interfaz": "USB 3.0", "Puertos": "4 USB-A", "Velocidad indicada": "Hasta 5 Gbps, según empaque", "Cable integrado": "30 cm, según empaque", "Indicador": "LED, según empaque", "Color": "Negro", "Clasificación": "Producto original"}, "beneficios": [{"valor": "4 puertos", "titulo": "Multiplica tus conexiones", "descripcion": "Convierte una conexión USB-A en cuatro puertos disponibles."}, {"valor": "USB 3.0", "titulo": "Transferencia rápida", "descripcion": "El empaque indica una velocidad de hasta 5 Gbps."}, {"valor": "30 cm", "titulo": "Ubicación más cómoda", "descripcion": "Cable integrado para acercar los puertos al área de trabajo."}, {"valor": "LED", "titulo": "Estado visible", "descripcion": "Indicador integrado señalado en el empaque."}], "imagen": "https://conectatech-ec.github.io/imagenes/hub001/HUB001-01.webp", "banner": null, "url": "https://conectatech-ec.github.io/productos/hub001-hub-3-0-usb-a-a-usb-a-x4-puertos/", "entrega": "Quito: consulta retiro y opciones de entrega vigentes.", "garantia": null}',8.5,9.77,1,1792373091,'6b8b2f37d323c031afd6d05a567427fbc875a05688f0f4fdce61b373242b46b1') ON CONFLICT(sku) DO UPDATE SET data=excluded.data,promo=excluded.promo,pvp=excluded.pvp,available=excluded.available,verified_until=excluded.verified_until,inventory_digest=excluded.inventory_digest;
INSERT INTO products VALUES ('POWE003','{"sku": "POWE003", "nombre": "Batería portátil Philco FLP8202CV 20.000 mAh", "modelo": "FLP8202CV", "marca": "Philco", "categoria": "Powerbanks", "descripcion": "Lleva energía de reserva para acompañar tu día. La Philco FLP8202CV combina 20.000 mAh, carga USB-C PD de hasta 20 W y salida USB-A de hasta 22,5 W para equipos compatibles. Consulta el nivel de batería en su pantalla y elige la conexión que necesites.", "caracteristicas": {"Capacidad": "20.000 mAh a 3,7 V · 74 Wh", "USB-C": "Entrada y salida; salida PD de hasta 20 W", "USB-A": "Salida de hasta 22,5 W", "Indicador": "Pantalla de nivel de carga", "Color": "Azul"}, "beneficios": [{"valor": "20.000 mAh", "titulo": "Energía para llevar", "descripcion": "Una reserva portátil para tus dispositivos USB."}, {"valor": "USB-C · PD 20 W", "titulo": "Carga y recarga", "descripcion": "El mismo puerto permite cargar equipos y recargar la batería."}, {"valor": "USB-A · 22,5 W", "titulo": "Conecta tu cable USB", "descripcion": "Salida de hasta 22,5 W con equipos y cables compatibles."}, {"valor": "Pantalla de carga", "titulo": "Consulta tu energía", "descripcion": "Revisa el nivel de carga de un vistazo."}], "imagen": "https://conectatech-ec.github.io/imagenes/powe003/POWE003-01.webp", "banner": null, "url": "https://conectatech-ec.github.io/productos/powe003-powerbank-philco-20000mah/", "entrega": "Quito: consulta retiro y opciones de entrega vigentes.", "garantia": null}',33.01,37.96,1,1792373091,'d280a0f91d9373b604ff46f8435a70bbd5ef63a9ce84fc62d0184f9ece99e91a') ON CONFLICT(sku) DO UPDATE SET data=excluded.data,promo=excluded.promo,pvp=excluded.pvp,available=excluded.available,verified_until=excluded.verified_until,inventory_digest=excluded.inventory_digest;
INSERT INTO audit VALUES ('inventory:66505c7a23be1a089689833940a8c3dc889a4b5d8e889e4998aa87a3ec74a983','SISTEMA','INVENTARIO','IMPORTADO','{"source_sha256": "66505c7a23be1a089689833940a8c3dc889a4b5d8e889e4998aa87a3ec74a983", "source_file": "Reporte-Inventario al 16-10-2026.xlsx"}',1792200391) ON CONFLICT(id) DO NOTHING;
UPDATE publications SET state='PENDIENTE' WHERE state IN ('PREPARADO','APROBADO') AND EXISTS (SELECT 1 FROM products p WHERE p.sku=publications.sku AND (p.available=0 OR p.inventory_digest!=publications.inventory_digest));
